procedure ship_order(
        p_order_id in lom_orders.order_id%type
    ) is
    begin
        update lom_shipments
           set status = 'SHIPPED',
               shipped_date = sysdate
         where order_id = p_order_id;

        if sql%rowcount = 0 then
            raise_application_error(
                gc_err_order_not_found,
                'LOM_ORDER_API.ship_order: no shipment found for order '
                    || p_order_id
            );
        end if;

        transition_status(p_order_id, 'SHIPPED');
    end ship_order;

function get_status(
        p_customer_id in lom_customers.customer_id%type
    ) return lom_customers.status%type is
        v_status lom_customers.status%type;
    begin
        select status into v_status
          from lom_customers
         where customer_id = p_customer_id;
        return v_status;
    exception
        when no_data_found then
            raise_application_error(
                gc_err_customer_not_found,
                'LOM_CUSTOMER_API.get_status: customer '
                    || p_customer_id || ' not found'
            );
    end get_status;

procedure transition_status(
        p_order_id   in lom_orders.order_id%type,
        p_new_status in lom_orders.status%type,
        p_changed_by in varchar2 default user
    ) is
        v_current_status lom_orders.status%type;
    begin
        select status into v_current_status
          from lom_orders
         where order_id = p_order_id
           for update;

        if not is_valid_transition(v_current_status, p_new_status) then
            raise_application_error(
                gc_err_invalid_transition,
                'LOM_ORDER_API.transition_status: cannot move order '
                    || p_order_id || ' from ' || v_current_status
                    || ' to ' || p_new_status
            );
        end if;

        update lom_orders
           set status = p_new_status,
               updated_date = sysdate
         where order_id = p_order_id;

        lom_audit_api.log_event(
            p_entity_name => 'ORDER',
            p_entity_id   => to_char(p_order_id),
            p_action      => 'STATUS_CHANGE',
            p_old_value   => v_current_status,
            p_new_value   => p_new_status,
            p_changed_by  => p_changed_by
        );
    exception
        when no_data_found then
            raise_application_error(
                gc_err_order_not_found,
                'LOM_ORDER_API.transition_status: order '
                    || p_order_id || ' not found'
            );
    end transition_status;

procedure set_credit_limit(
        p_customer_id in lom_customers.customer_id%type,
        p_new_limit   in lom_customers.credit_limit%type,
        p_changed_by  in varchar2 default user
    ) is
        v_old_limit lom_customers.credit_limit%type;
    begin
        if p_new_limit < 0 then
            raise_application_error(
                gc_err_negative_credit,
                'LOM_CUSTOMER_API.set_credit_limit: credit limit cannot be negative'
            );
        end if;

        select credit_limit into v_old_limit
          from lom_customers
         where customer_id = p_customer_id;

        update lom_customers
           set credit_limit = p_new_limit,
               updated_by = p_changed_by,
               updated_date = sysdate
         where customer_id = p_customer_id;

        lom_audit_api.log_event(
            p_entity_name => 'CUSTOMER',
            p_entity_id   => to_char(p_customer_id),
            p_action      => 'CREDIT_LIMIT_CHANGE',
            p_old_value   => to_char(v_old_limit),
            p_new_value   => to_char(p_new_limit),
            p_changed_by  => p_changed_by
        );
    exception
        when no_data_found then
            raise_application_error(
                gc_err_customer_not_found,
                'LOM_CUSTOMER_API.set_credit_limit: customer '
                    || p_customer_id || ' not found'
            );
    end set_credit_limit;

function has_open_orders(
        p_customer_id in lom_customers.customer_id%type
    ) return varchar2 is
        v_count pls_integer;
    begin
        select count(*) into v_count
          from lom_orders
         where customer_id = p_customer_id
           and status not in ('SHIPPED', 'REJECTED', 'CANCELLED');
        return case when v_count > 0 then 'Y' else 'N' end;
    end has_open_orders;

function calc_line_total(
        p_quantity   in number,
        p_unit_price in number,
        p_discount   in number default 0
    ) return number is
    begin
        return round((p_quantity * p_unit_price) - nvl(p_discount, 0), 2);
    end calc_line_total;

procedure adjust_quantity(
        p_product_id     in lom_inventory.product_id%type,
        p_warehouse_code in lom_inventory.warehouse_code%type,
        p_delta          in number,
        p_changed_by     in varchar2 default user
    ) is
        v_old_on_hand lom_inventory.quantity_on_hand%type;
        v_new_on_hand lom_inventory.quantity_on_hand%type;
    begin
        select quantity_on_hand into v_old_on_hand
          from lom_inventory
         where product_id = p_product_id
           and warehouse_code = p_warehouse_code
           for update;

        v_new_on_hand := v_old_on_hand + p_delta;

        if v_new_on_hand < 0 then
            raise_application_error(
                gc_err_insufficient_stock,
                'LOM_INVENTORY_API.adjust_quantity: resulting on-hand quantity would be negative'
            );
        end if;

        update lom_inventory
           set quantity_on_hand = v_new_on_hand,
               last_updated = sysdate
         where product_id = p_product_id
           and warehouse_code = p_warehouse_code;

        lom_audit_api.log_event(
            p_entity_name => 'INVENTORY',
            p_entity_id   => p_product_id || '/' || p_warehouse_code,
            p_action      => 'QUANTITY_ADJUSTMENT',
            p_old_value   => to_char(v_old_on_hand),
            p_new_value   => to_char(v_new_on_hand),
            p_changed_by  => p_changed_by
        );
    end adjust_quantity;

procedure release_order(
        p_order_id in lom_orders.order_id%type
    ) is
        v_current_status lom_orders.status%type;
        v_warehouse_code lom_orders.warehouse_code%type;
    begin
        select status, warehouse_code into v_current_status, v_warehouse_code
          from lom_orders
         where order_id = p_order_id;

        if v_current_status <> 'APPROVED' then
            raise_application_error(
                gc_err_invalid_transition,
                'LOM_ORDER_API.release_order: order '
                    || p_order_id || ' is not APPROVED'
            );
        end if;

        for r in (
            select product_id, quantity
              from lom_order_lines
             where order_id = p_order_id
        ) loop
            lom_inventory_api.reserve_quantity(
                p_product_id     => r.product_id,
                p_warehouse_code => v_warehouse_code,
                p_quantity       => r.quantity
            );
        end loop;

        transition_status(p_order_id, 'RELEASED');

        insert into lom_shipments (
            shipment_id, order_id, warehouse_code, status, created_date
        ) values (
            lom_shipment_id_seq.nextval, p_order_id, v_warehouse_code, 'PENDING', sysdate
        );
    exception
        when no_data_found then
            raise_application_error(
                gc_err_order_not_found,
                'LOM_ORDER_API.release_order: order '
                    || p_order_id || ' not found'
            );
    end release_order;

procedure submit_order(
        p_order_id in lom_orders.order_id%type
    ) is
        v_current_status lom_orders.status%type;
        v_needs_approval lom_orders.approval_required%type;
    begin
        select status into v_current_status
          from lom_orders
         where order_id = p_order_id;

        if v_current_status <> 'DRAFT' then
            raise_application_error(
                gc_err_invalid_transition,
                'LOM_ORDER_API.submit_order: order '
                    || p_order_id || ' is not in DRAFT status'
            );
        end if;

        recalc_order_totals(p_order_id);

        select approval_required into v_needs_approval
          from lom_orders
         where order_id = p_order_id;

        transition_status(p_order_id, 'SUBMITTED');

        if v_needs_approval = 'Y' then
            transition_status(p_order_id, 'PENDING_APPROVAL');
            lom_approval_api.create_approval_request(p_order_id);
        else
            transition_status(p_order_id, 'APPROVED');
        end if;
    exception
        when no_data_found then
            raise_application_error(
                gc_err_order_not_found,
                'LOM_ORDER_API.submit_order: order '
                    || p_order_id || ' not found'
            );
    end submit_order;

function is_valid_transition(
        p_from in lom_orders.status%type,
        p_to   in lom_orders.status%type
    ) return boolean is
    begin
        return (p_from = 'DRAFT'             and p_to = 'SUBMITTED')
            or (p_from = 'SUBMITTED'         and p_to = 'PENDING_APPROVAL')
            or (p_from = 'SUBMITTED'         and p_to = 'APPROVED')
            or (p_from = 'PENDING_APPROVAL'  and p_to = 'APPROVED')
            or (p_from = 'PENDING_APPROVAL'  and p_to = 'REJECTED')
            or (p_from = 'APPROVED'          and p_to = 'RELEASED')
            or (p_from = 'RELEASED'          and p_to = 'SHIPPED')
            or (p_from = 'DRAFT'             and p_to = 'CANCELLED')
            or (p_from = 'SUBMITTED'         and p_to = 'CANCELLED')
            or (p_from = 'PENDING_APPROVAL'  and p_to = 'CANCELLED');
    end is_valid_transition;

function validate_quantity(
        p_product_id     in lom_inventory.product_id%type,
        p_warehouse_code in lom_inventory.warehouse_code%type,
        p_quantity       in number
    ) return varchar2 is
        v_available number;
    begin
        v_available := get_available_qty(p_product_id, p_warehouse_code);
        if p_quantity > v_available then
            return 'Only ' || v_available
                || ' unit(s) available in warehouse ' || p_warehouse_code;
        end if;
        return null;
    end validate_quantity;

function can_place_order(
        p_customer_id in lom_customers.customer_id%type
    ) return varchar2 is
    begin
        if get_status(p_customer_id) = 'ACTIVE' then
            return 'Y';
        else
            return 'N';
        end if;
    end can_place_order;

function default_warehouse return lom_warehouses.warehouse_code%type is
        v_warehouse_code lom_warehouses.warehouse_code%type;
    begin
        select warehouse_code into v_warehouse_code
          from lom_warehouses
         where is_default = 'Y'
           and rownum = 1;
        return v_warehouse_code;
    exception
        when no_data_found then
            raise_application_error(
                gc_err_no_default_warehouse,
                'LOM_INVENTORY_API.default_warehouse: no warehouse is flagged as default'
            );
    end default_warehouse;

procedure reserve_quantity(
        p_product_id     in lom_inventory.product_id%type,
        p_warehouse_code in lom_inventory.warehouse_code%type,
        p_quantity       in number
    ) is
    begin
        update lom_inventory
           set quantity_reserved = quantity_reserved + p_quantity,
               last_updated = sysdate
         where product_id = p_product_id
           and warehouse_code = p_warehouse_code
           and quantity_on_hand - quantity_reserved >= p_quantity;

        if sql%rowcount = 0 then
            raise_application_error(
                gc_err_insufficient_stock,
                'LOM_INVENTORY_API.reserve_quantity: insufficient stock for product '
                    || p_product_id || ' in warehouse ' || p_warehouse_code
            );
        end if;
    end reserve_quantity;

procedure create_approval_request(
        p_order_id     in lom_orders.order_id%type,
        p_requested_by in varchar2 default user
    ) is
    begin
        insert into lom_approvals (
            approval_id, order_id, status, requested_by, requested_date
        ) values (
            lom_approval_id_seq.nextval, p_order_id, 'PENDING', p_requested_by, sysdate
        );

        lom_audit_api.log_event(
            p_entity_name => 'APPROVAL',
            p_entity_id   => to_char(p_order_id),
            p_action      => 'REQUESTED',
            p_new_value   => 'PENDING',
            p_changed_by  => p_requested_by
        );
    end create_approval_request;

procedure change_status(
        p_customer_id in lom_customers.customer_id%type,
        p_new_status  in lom_customers.status%type,
        p_changed_by  in varchar2 default user,
        p_reason      in varchar2 default null
    ) is
        v_old_status lom_customers.status%type;
    begin
        if p_new_status not in ('ACTIVE', 'INACTIVE') then
            raise_application_error(
                gc_err_invalid_status,
                'LOM_CUSTOMER_API.change_status: invalid status '
                    || p_new_status
            );
        end if;

        v_old_status := get_status(p_customer_id);

        if p_new_status = 'INACTIVE' and has_open_orders(p_customer_id) = 'Y' then
            raise_application_error(
                gc_err_open_orders,
                'LOM_CUSTOMER_API.change_status: customer '
                    || p_customer_id
                    || ' has open orders and cannot be inactivated'
            );
        end if;

        update lom_customers
           set status = p_new_status,
               updated_by = p_changed_by,
               updated_date = sysdate
         where customer_id = p_customer_id;

        lom_audit_api.log_event(
            p_entity_name => 'CUSTOMER',
            p_entity_id   => to_char(p_customer_id),
            p_action      => 'STATUS_CHANGE',
            p_old_value   => v_old_status,
            p_new_value   => p_new_status,
            p_notes       => p_reason,
            p_changed_by  => p_changed_by
        );
    end change_status;

procedure recalc_order_totals(
        p_order_id in lom_orders.order_id%type
    ) is
        v_subtotal lom_orders.subtotal%type;
        v_tax      lom_orders.tax_amount%type;
        v_total    lom_orders.total_amount%type;
    begin
        select nvl(sum(line_total), 0) into v_subtotal
          from lom_order_lines
         where order_id = p_order_id;

        v_tax   := round(v_subtotal * gc_tax_rate, 2);
        v_total := v_subtotal + v_tax;

        update lom_orders
           set subtotal = v_subtotal,
               tax_amount = v_tax,
               total_amount = v_total,
               approval_required = requires_approval(v_total),
               updated_date = sysdate
         where order_id = p_order_id;

        if sql%rowcount = 0 then
            raise_application_error(
                gc_err_order_not_found,
                'LOM_ORDER_API.recalc_order_totals: order '
                    || p_order_id || ' not found'
            );
        end if;
    end recalc_order_totals;

function requires_approval(
        p_total_amount in number
    ) return varchar2 is
    begin
        return case when p_total_amount > gc_approval_threshold then 'Y' else 'N' end;
    end requires_approval;

procedure reject(
        p_approval_id in lom_approvals.approval_id%type,
        p_approver    in varchar2 default user,
        p_comments    in varchar2
    ) is
        v_order_id lom_approvals.order_id%type;
    begin
        if p_comments is null then
            raise_application_error(
                gc_err_comments_required,
                'LOM_APPROVAL_API.reject: a rejection reason is required'
            );
        end if;

        select order_id into v_order_id
          from lom_approvals
         where approval_id = p_approval_id
           for update;

        update lom_approvals
           set status = 'REJECTED',
               approver = p_approver,
               comments = p_comments,
               approval_date = sysdate
         where approval_id = p_approval_id;

        lom_audit_api.log_event(
            p_entity_name => 'APPROVAL',
            p_entity_id   => to_char(p_approval_id),
            p_action      => 'REJECTED',
            p_old_value   => 'PENDING',
            p_new_value   => 'REJECTED',
            p_notes       => p_comments,
            p_changed_by  => p_approver
        );

        lom_order_api.transition_status(v_order_id, 'REJECTED', p_approver);
    exception
        when no_data_found then
            raise_application_error(
                gc_err_approval_not_found,
                'LOM_APPROVAL_API.reject: approval '
                    || p_approval_id || ' not found'
            );
    end reject;

function get_available_qty(
        p_product_id     in lom_inventory.product_id%type,
        p_warehouse_code in lom_inventory.warehouse_code%type
    ) return number is
        v_available number;
    begin
        select quantity_available into v_available
          from lom_inventory
         where product_id = p_product_id
           and warehouse_code = p_warehouse_code;
        return v_available;
    exception
        when no_data_found then
            return 0;
    end get_available_qty;

DECLARE
  v_button PLS_INTEGER;
BEGIN
  IF :BK_ORDER.STATUS != 'DRAFT' THEN
    om_shared.show_message('Only DRAFT orders can be submitted.');
    RETURN;
  END IF;

  v_button := SHOW_ALERT('AL_CONFIRM_SUBMIT');
  IF v_button != ALERT_BUTTON1 THEN
    RETURN;
  END IF;

  COMMIT_FORM;

  lom_order_api.submit_order(:BK_ORDER.ORDER_ID);
  COMMIT;
  om_shared.show_message('Order ' || :BK_ORDER.ORDER_ID || ' submitted.');
  EXECUTE_QUERY;
EXCEPTION
  WHEN OTHERS THEN
    ROLLBACK;
    om_shared.show_message('Submit failed: ' || SQLERRM);
END;

BEGIN
  CLEAR_FORM(NO_VALIDATE);
  GO_BLOCK('BK_ORDER');
  CREATE_RECORD;
END;

BEGIN
  :GLOBAL.G_USER := NVL(:GLOBAL.G_USER, GET_APPLICATION_PROPERTY(USERNAME));
  GO_BLOCK('BK_APPROVAL');
  EXECUTE_QUERY;
END;

BEGIN
  IF :BK_CUSTOMER.EMAIL IS NOT NULL
     AND NOT REGEXP_LIKE(:BK_CUSTOMER.EMAIL, '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$') THEN
    om_shared.show_message('Email address does not look valid.');
    RAISE FORM_TRIGGER_FAILURE;
  END IF;
END;

BEGIN
  IF :BK_INVENTORY.QUANTITY_AVAILABLE <= :BK_INVENTORY.REORDER_LEVEL THEN
    :BK_INVENTORY.LOW_STOCK_FLAG := 'YES';
  ELSE
    :BK_INVENTORY.LOW_STOCK_FLAG := NULL;
  END IF;
END;

DECLARE
  v_can_place VARCHAR2(1);
BEGIN
  BEGIN
    SELECT customer_name INTO :BK_ORDER.CUSTOMER_NAME
      FROM lom_customers
     WHERE customer_id = :BK_ORDER.CUSTOMER_ID;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      om_shared.show_message('Customer ' || :BK_ORDER.CUSTOMER_ID || ' not found.');
      RAISE FORM_TRIGGER_FAILURE;
  END;

  v_can_place := lom_customer_api.can_place_order(:BK_ORDER.CUSTOMER_ID);
  IF v_can_place = 'N' THEN
    om_shared.show_message('Customer ' || :BK_ORDER.CUSTOMER_ID
      || ' is not ACTIVE and cannot place new orders.');
    RAISE FORM_TRIGGER_FAILURE;
  END IF;
END;

BEGIN
  IF :BK_CUSTOMER.CREDIT_LIMIT < 0 THEN
    om_shared.show_message('Credit limit cannot be negative.');
    RAISE FORM_TRIGGER_FAILURE;
  END IF;
END;

BEGIN
  lom_order_api.recalc_order_totals(:BK_ORDER.ORDER_ID);
END;

BEGIN
  IF :BK_INVENTORY.P_ADJUST_QTY IS NULL OR :BK_INVENTORY.P_ADJUST_QTY = 0 THEN
    om_shared.show_message('Enter a non-zero adjustment quantity first.');
    RETURN;
  END IF;

  lom_inventory_api.adjust_quantity(
    p_product_id     => :BK_INVENTORY.PRODUCT_ID,
    p_warehouse_code => :BK_INVENTORY.WAREHOUSE_CODE,
    p_delta          => :BK_INVENTORY.P_ADJUST_QTY,
    p_changed_by     => :GLOBAL.G_USER
  );
  COMMIT;
  :BK_INVENTORY.P_ADJUST_QTY := NULL;
  om_shared.show_message('Inventory adjusted.');
  EXECUTE_QUERY;
EXCEPTION
  WHEN OTHERS THEN
    ROLLBACK;
    om_shared.show_message('Adjustment failed: ' || SQLERRM);
END;

BEGIN
  -- See 's sibling note on BT_APPROVE above.
  SHOW_ALERT('AL_CONFIRM_REJECT');
  IF :SYSTEM.ALERT_BUTTON = ALERT_BUTTON1 THEN
    UPDATE lom_approvals
       SET status = 'REJECTED',
           approver = :GLOBAL.G_USER,
           approval_date = SYSDATE,
           comments = :BK_APPROVAL.COMMENTS
     WHERE approval_id = :BK_APPROVAL.APPROVAL_ID;

    UPDATE lom_orders
       SET status = 'REJECTED'
     WHERE order_id = :BK_APPROVAL.ORDER_ID;

    COMMIT;
    om_shared.show_message('Order rejected.');
    EXECUTE_QUERY;
  END IF;
EXCEPTION
  WHEN OTHERS THEN
    ROLLBACK;
    om_shared.show_message('Rejection failed: ' || SQLERRM);
END;

DECLARE
  v_available NUMBER;
BEGIN
  SELECT NVL(quantity_available, 0) INTO v_available
    FROM lom_inventory
   WHERE product_id = :BK_ORDER_LINE.PRODUCT_ID
     AND warehouse_code = :BK_ORDER.WAREHOUSE_CODE;

  IF :BK_ORDER_LINE.QUANTITY > v_available THEN
    om_shared.show_message('Only ' || v_available || ' unit(s) available for product '
      || :BK_ORDER_LINE.PRODUCT_ID || ' in warehouse ' || :BK_ORDER.WAREHOUSE_CODE);
    RAISE FORM_TRIGGER_FAILURE;
  END IF;

  :BK_ORDER_LINE.LINE_TOTAL := ROUND(
    (:BK_ORDER_LINE.QUANTITY * :BK_ORDER_LINE.UNIT_PRICE) - NVL(:BK_ORDER_LINE.DISCOUNT_AMOUNT, 0), 2);
END;

BEGIN
  :GLOBAL.G_USER := NVL(:GLOBAL.G_USER, GET_APPLICATION_PROPERTY(USERNAME));
  GO_BLOCK('BK_INVENTORY');
  EXECUTE_QUERY;
END;

BEGIN
  SELECT product_name, unit_price
    INTO :BK_ORDER_LINE.PRODUCT_NAME, :BK_ORDER_LINE.UNIT_PRICE
    FROM lom_products
   WHERE product_id = :BK_ORDER_LINE.PRODUCT_ID
     AND active_flag = 'Y';
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    om_shared.show_message('Product ' || :BK_ORDER_LINE.PRODUCT_ID || ' not found or inactive.');
    RAISE FORM_TRIGGER_FAILURE;
END;

DECLARE
  v_default_limit lom_customer_types.default_credit_limit%TYPE;
BEGIN
  SELECT default_credit_limit INTO v_default_limit
    FROM lom_customer_types
   WHERE customer_type_code = :BK_CUSTOMER.CUSTOMER_TYPE_CODE;

  IF :BK_CUSTOMER.CREDIT_LIMIT IS NULL THEN
    COPY(TO_CHAR(v_default_limit), 'BK_CUSTOMER.CREDIT_LIMIT');
  END IF;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    NULL;
END;

BEGIN
  :GLOBAL.G_USER := NVL(:GLOBAL.G_USER, GET_APPLICATION_PROPERTY(USERNAME));
  IF :PARAMETER.P_ORDER_ID IS NOT NULL THEN
    SET_BLOCK_PROPERTY('BK_ORDER', DEFAULT_WHERE, 'ORDER_ID = ' || :PARAMETER.P_ORDER_ID);
    GO_BLOCK('BK_ORDER');
    EXECUTE_QUERY;
  ELSE
    GO_BLOCK('BK_ORDER');
  END IF;
END;

BEGIN
  lom_order_api.recalc_order_totals(:BK_ORDER.ORDER_ID);
END;

BEGIN
  -- Baseline for the POST-UPDATE audit trigger below: Forms has no
  -- built-in "old value" accessor, so the pre-change STATUS is stashed
  :GLOBAL.G_OLD_STATUS := :BK_CUSTOMER.STATUS;
END;

BEGIN
  SET_ITEM_PROPERTY('BK_ORDER.STATUS', ENABLED, PROPERTY_FALSE);
  SET_ITEM_PROPERTY('BK_ORDER.SUBTOTAL', ENABLED, PROPERTY_FALSE);
  SET_ITEM_PROPERTY('BK_ORDER.TAX_AMOUNT', ENABLED, PROPERTY_FALSE);
  SET_ITEM_PROPERTY('BK_ORDER.TOTAL_AMOUNT', ENABLED, PROPERTY_FALSE);
  SET_ITEM_PROPERTY('BK_ORDER.APPROVAL_REQUIRED', ENABLED, PROPERTY_FALSE);
  SET_ITEM_PROPERTY('BK_ORDER.CREATED_BY', ENABLED, PROPERTY_FALSE);
  SET_ITEM_PROPERTY('BK_ORDER.CREATED_DATE', ENABLED, PROPERTY_FALSE);
END;

BEGIN
  -- ) and LOM_AUDIT_API.log_event. A mechanical translation of
  SHOW_ALERT('AL_CONFIRM_APPROVE');
  IF :SYSTEM.ALERT_BUTTON = ALERT_BUTTON1 THEN
    UPDATE lom_approvals
       SET status = 'APPROVED',
           approver = :GLOBAL.G_USER,
           approval_date = SYSDATE
     WHERE approval_id = :BK_APPROVAL.APPROVAL_ID;

    UPDATE lom_orders
       SET status = 'APPROVED'
     WHERE order_id = :BK_APPROVAL.ORDER_ID;

    COMMIT;
    om_shared.show_message('Order approved.');
    EXECUTE_QUERY;
  END IF;
EXCEPTION
  WHEN OTHERS THEN
    ROLLBACK;
    om_shared.show_message('Approval failed: ' || SQLERRM);
END;

